option.value:
.App {
  text-align: center;
  padding: 20px;
  font-family: Arial, sans-serif;
}

h1 {
  color: #333;
  margin: 20px 0;
}

p {
  color: #666;
  font-size: 16px;
}

.app-shell {
  min-height: 100vh;
  background: linear-gradient(180deg, #f7f9fc 0%, #eef3ff 100%);
  color: #1f2937;
}

.home {
  max-width: 1100px;
  margin: 0 auto;
  padding: 72px 24px 48px;
}

.hero {
  text-align: center;
  padding: 56px 24px 40px;
}

.hero-badge {
  display: inline-block;
  margin: 0 0 16px;
  padding: 8px 14px;
  border-radius: 999px;
  background: #dbeafe;
  color: #1d4ed8;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.hero h1 {
  margin: 0;
  font-size: clamp(2rem, 4vw, 3.5rem);
  line-height: 1.1;
}

.hero-description {
  max-width: 720px;
  margin: 18px auto 0;
  color: #4b5563;
  font-size: 1.05rem;
  line-height: 1.7;
}

.hero-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 28px;
}

.primary-btn,
.secondary-btn {
  border: none;
  border-radius: 12px;
  padding: 12px 18px;
  font-size: 0.98rem;
  font-weight: 700;
  cursor: pointer;
}

.primary-btn {
  background: #2563eb;
  color: #fff;
}

.secondary-btn {
  background: #ffffff;
  color: #2563eb;
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.12);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  margin-top: 32px;
}

.stat-card,
.feature-item {
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #e5e7eb;
  border-radius: 18px;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
}

.stat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 24px 16px;
}

.stat-value {
  font-size: 2rem;
  font-weight: 800;
  color: #2563eb;
}

.stat-label {
  color: #4b5563;
  font-weight: 600;
}

.feature-section {
  margin-top: 42px;
}

.feature-section h2 {
  margin-bottom: 18px;
  font-size: 1.5rem;
}

.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}

.feature-item {
  padding: 22px;
}

.feature-item h3 {
  margin: 0 0 10px;
}

.feature-item p {
  margin: 0;
  color: #4b5563;
  line-height: 1.6;
}
